export function horizonElevationAt(profile, azimuthDeg, mastHeightM) {
  if (!profile || !profile.elevationsDegByHeight?.length) return 0;
  const heights = profile.mastHeightsM;
  const rows = profile.elevationsDegByHeight;
  const h = Math.max(heights[0], Math.min(heights[heights.length - 1], mastHeightM));
  let lo = 0;
  for (let i = 1; i < heights.length; i += 1) {
    if (heights[i] >= h) {
      lo = i - 1;
      break;
    }
    lo = i;
  }
  const hi = Math.min(heights.length - 1, lo + 1);
  const h0 = heights[lo];
  const h1 = heights[hi];
  const hFrac = h1 === h0 ? 0 : (h - h0) / (h1 - h0);
  const az = ((azimuthDeg % 360) + 360) % 360;
  const bins = profile.binCount;
  const raw = az / profile.binWidthDeg;
  const i0 = Math.floor(raw) % bins;
  const i1 = (i0 + 1) % bins;
  const frac = raw - Math.floor(raw);
  const rowLo = rows[lo];
  const rowHi = rows[hi];
  const loValue = rowLo[i0] * (1 - frac) + rowLo[i1] * frac;
  const hiValue = rowHi[i0] * (1 - frac) + rowHi[i1] * frac;
  return loValue * (1 - hFrac) + hiValue * hFrac;
}

function customHorizon(azimuthDeg) {
  const rad = (azimuthDeg * Math.PI) / 180;
  return 0.35 + 0.55 * Math.sin(rad + 0.6) + 0.18 * Math.cos(2 * rad);
}

function adaptSite(record) {
  const ui = SITE_UI[record.id] ?? {};
  const role = record.role ?? (record.id === 'control_eq' ? 'reference' : 'candidate');
  const isRealLola = Boolean(record.demSourceNear) || Boolean(record.horizonMode?.startsWith('lola'));
  const site = {
    ...record,
    id: record.id,
    name: ui.displayName ?? record.name,
    shortName: ui.shortName ?? record.shortName ?? record.name,
    program: ui.program ?? 'Candidato lunar',
    targetMission: ui.targetMission ?? record.name,
    description: ui.descriptionEs ?? record.description,
    role,
    lat: record.latDeg,
    lon: record.lonEastDeg,
    elevationKm: (record.elevationM ?? 0) / 1000,
    elevationM: record.elevationM ?? 0,
    maxSlopeDeg: record.slopeDeg ?? 0,
    avgSlopeDeg: record.slopeDeg ?? 0,
    distToIceTrapKm: ui.iceKm ?? 0,
    optimalPanelAzimuthDeg: record.optimalPanelAzimuthDeg ?? 0,
    dataQuality:
      record.dataQuality ??
      (record.horizonMode === 'lola_hybrid'
        ? 'LOLA 5 m/px + 80 m/px'
        : record.horizonMode === 'lola_regional_80m'
          ? 'LOLA 80 m/px regional'
          : record.horizonMode === 'analytic_flat'
            ? 'Horizonte analítico'
            : 'Aproximado'),
    horizonSource: record.horizonSource ?? record.horizonMode ?? 'unknown',
    ephemSource:
      record.ephemSource ??
      (REFERENCE_EPHEM_IDS.has(record.id) ? 'jpl_horizons' : 'iau2000_local'),
    isRealLola,
    mastHeightM: 2,
    horizon: null,
    ephem: null
  };
  site.horizonAt = (azimuthDeg, height = site.mastHeightM) => {
    if (site.horizon) return horizonElevationAt(site.horizon, azimuthDeg, height);
    return customHorizon(azimuthDeg);
  };
  site.horizonProfile = (azimuthDeg) => site.horizonAt(azimuthDeg, site.mastHeightM);
  return site;
}

async function fetchJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.json();
}

/**
 * Loads the metadata and all LOLA horizon profiles. The seven primary sites
 * are required; the two regional-80 m sites are optional so the app still
 * boots if their generated files are absent.
 */
export async function loadLandingSites() {
  const base = `${import.meta.env.BASE_URL}data/`;
  const catalog = await fetchJson(`${base}sites.json`);
  let extra = { sites: [] };
  try {
    extra = await fetchJson(`${base}sites-extra.json`);
  } catch {
    extra = { sites: [] };
  }
  const records = [...catalog.sites, ...(extra.sites ?? [])];
  const sites = records.map(adaptSite);

  await Promise.all(
    sites.map(async (site) => {
      const file = site.horizonFile ?? `horizon/${site.id}.json`;
      try {
        site.horizon = await fetchJson(`${base}${file}`);
      } catch (error) {
        if (site.id !== 'nobile_rim_1' && site.id !== 'haworth_rim') throw error;
        site.horizon = null;
        site.dataQuality = 'Sin DEM LOLA disponible';
        site.isRealLola = false;
        site.horizonSource = 'unavailable';
      }
    })
  );

  const order = ['site23', 'site01', 'site04', 'site07', 'site11', 'site20', 'nobile_rim_1', 'haworth_rim', 'control_eq'];
  sites.sort((a, b) => {
    const ia = order.indexOf(a.id);
    const ib = order.indexOf(b.id);
    return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
  });
  LANDING_SITES = sites;
  return sites;
}

export function setMastHeight(sites, heightM) {
  for (const site of sites) site.mastHeightM = heightM;
}

export function getCustomSite(lat, lon, name = 'Sitio personalizado') {
  const normLon = ((lon % 360) + 360) % 360;
  const isSouthPole = lat < -75;
  const distToPoleKm = (90 - Math.abs(lat)) * 30.3;
  const avgSlope = isSouthPole
    ? 4.5 + Math.abs(Math.sin(lat * 5 + lon * 2)) * 5.0
    : 2.5 + Math.abs(Math.sin(lon)) * 2.0;
  const maxSlope = avgSlope * 1.8 + 1.2;
  const elevation = isSouthPole ? 1.0 + 3.0 * Math.sin(normLon * (Math.PI / 180)) : -1.0;
  const site = {
    id: 'custom-site',
    name: `${name} (${lat.toFixed(2)}°, ${normLon.toFixed(2)}°)`,
    shortName: 'Personalizado',
    program: 'Coordenadas definidas por el usuario',
    targetMission: 'Misión simulada',
    role: 'custom',
    lat,
    lon: normLon,
    latDeg: lat,
    lonEastDeg: normLon,
    elevationKm: elevation,
    elevationM: elevation * 1000,
    maxSlopeDeg: parseFloat(maxSlope.toFixed(1)),
    avgSlopeDeg: parseFloat(avgSlope.toFixed(1)),
    slopeDeg: parseFloat(avgSlope.toFixed(1)),
    distToIceTrapKm: isSouthPole ? Math.max(1.0, distToPoleKm * 0.4) : 2500,
    optimalPanelAzimuthDeg: 0,
    description:
      'Sitio definido por el usuario. Se evalúa con el motor de efemérides local y un horizonte aproximado; no usa un DEM LOLA y no debe interpretarse como una certificación del terreno.',
    dataQuality: 'Modelo aproximado (sin DEM LOLA)',
    horizonSource: 'approx',
    ephemSource: 'iau2000_local',
    isRealLola: false,
    mastHeightM: 2,
    horizon: null,
    ephem: null
  };
  site.horizonAt = (azimuthDeg) => customHorizon(azimuthDeg);
  site.horizonProfile = (azimuthDeg) => customHorizon(azimuthDeg);
  return site;
}
